insert into public.recipes (id, owner_id, name, description, cuisine, meal_types, servings, prep_mins, cook_mins, storage, keeps_days, freezable, tags, equipment, difficulty, emoji, hue, source) values ('spaghetti-bolognese', null, 'Weeknight spaghetti bolognese', 'A rich beef and tomato ragù with hidden veg. Makes a generous batch that freezes well.', 'italian', array['dinner']::public.meal_slot[], 4, 15, 40, 'Cool quickly, then keep covered in the fridge for up to 3 days. Reheat until piping hot throughout. Cool quickly and freeze in portions for up to 3 months. Defrost overnight in the fridge and reheat until piping hot.', 3, true, array['family-friendly', 'batch-cook', 'comfort']::text[], array['hob']::text[], 'easy', '🍝', 12, 'original') on conflict (id) do nothing;
