insert into public.recipe_steps values ('spaghetti-bolognese', 0, 'Heat the oil in a large pan and soften the onion, carrot and celery for 8–10 minutes.') on conflict do nothing;
insert into public.recipe_steps values ('spaghetti-bolognese', 1, 'Add the garlic for 1 minute, then the mince. Brown it, breaking it up with a spoon.') on conflict do nothing;
insert into public.recipe_steps values ('spaghetti-bolognese', 2, 'Stir in the tomato purée, chopped tomatoes, stock and oregano. Simmer gently, partly covered, for 30 minutes until thick.') on conflict do nothing;
